/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    PlannerPipelineStepSchema, PlannerPipelineStep, PlannerPipelineSchema, PlannerPipeline, compileStructuralPlannerPipeline, listPlannerFamilies
 * depends    src/mechanics/ep-graph, tooling/sdk-graph
 * used by    tooling/planner-engine/codegen, tooling/planner-engine/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { z } from 'zod'
import { loadEpGraph } from '../../src/mechanics/ep-graph'
import { loadSdkGraphWithTrust, buildSdkGraphIndex } from '../sdk-graph'

export const PlannerPipelineStepSchema = z.object({
  id: z.string().min(1),
  kind: z.enum([
    'read-controls',
    'read-candidates',
    'apply-gates',
    'eval-costs',
    'rank',
    'emit-path',
    'unmodeled',
  ]),
  nodeIds: z.array(z.string()).default([]),
  cellRefs: z.array(z.string()).default([]),
  status: z.enum(['ready', 'researching', 'blocked']),
  note: z.string().optional(),
})
export type PlannerPipelineStep = z.infer<typeof PlannerPipelineStepSchema>

export const PlannerPipelineSchema = z.object({
  family: z.string().min(1),
  generatedAt: z.string(),
  source: z.literal('graph'),
  /** citations = graph FORMULATEXT/lambda emitted; deferred = none yet */
  codegen: z.enum(['deferred', 'citations']),
  steps: z.array(PlannerPipelineStepSchema),
  unmodeledNodeIds: z.array(z.string()).default([]),
  warnings: z.array(z.string()).default([]),
})
export type PlannerPipeline = z.infer<typeof PlannerPipelineSchema>

/**
 * Structural planner pipeline from EP/SDK graphs (no formula invent).
 */
export function compileStructuralPlannerPipeline(family: string): PlannerPipeline {
  const ep = loadEpGraph()
  const { graph } = loadSdkGraphWithTrust({
    mode: 'degraded',
    scanPlannerCitations: false,
    checkDebugGraph: false,
  })
  const index = buildSdkGraphIndex(graph)

  const familyKey = family.startsWith('ep.') ? family : `ep.${family}`
  const alt = family.startsWith('ep.') ? family.slice(3) : family

  const nodes = Object.values(graph.nodes).filter(n => {
    const f = String(n.family)
    return f === family || f === familyKey || f === alt || f.endsWith(`.${alt}`)
  })
  const epNodes = Object.values(ep.nodes).filter(n => n.family === alt || n.family === family)

  const byType = new Map<string, string[]>()
  for (const n of [...nodes, ...epNodes]) {
    const list = byType.get(n.type) ?? []
    if (!list.includes(n.id)) list.push(n.id)
    byType.set(n.type, list)
  }

  const cellRefs: string[] = []
  for (const n of nodes) {
    for (const c of n.sourceCells ?? []) {
      cellRefs.push(`${c.sheet}!${c.cell}`)
    }
  }

  const unmodeled = [...nodes, ...epNodes]
    .filter(n => n.status === 'researching' || (n as { status?: string }).status === 'unmodeled')
    .map(n => n.id)

  const steps: PlannerPipelineStep[] = [
    {
      id: 'controls',
      kind: 'read-controls',
      nodeIds: byType.get('control') ?? [],
      cellRefs: cellRefs.slice(0, 40),
      status: (byType.get('control')?.length ?? 0) > 0 ? 'ready' : 'researching',
      note: 'Structural controls from graph',
    },
    {
      id: 'candidates',
      kind: 'read-candidates',
      nodeIds: byType.get('candidate') ?? [],
      cellRefs: [],
      status: (byType.get('candidate')?.length ?? 0) > 0 ? 'ready' : 'researching',
    },
    {
      id: 'gates',
      kind: 'apply-gates',
      nodeIds: byType.get('gate') ?? byType.get('hide') ?? [],
      cellRefs: [],
      status: 'researching',
      note: 'Awaiting FORMULATEXT citations on hide/gate nodes',
    },
    {
      id: 'costs',
      kind: 'eval-costs',
      nodeIds: [...(byType.get('lambda') ?? []), ...(byType.get('stat') ?? [])],
      cellRefs: [],
      status: 'blocked',
      note: 'Numeric eval stays in hand-ported planners until lambda citations emit',
    },
    {
      id: 'rank',
      kind: 'rank',
      nodeIds: [],
      cellRefs: [],
      status: 'blocked',
      note: 'Ranking codegen deferred',
    },
    {
      id: 'emit',
      kind: 'emit-path',
      nodeIds: byType.get('path') ?? byType.get('display') ?? [],
      cellRefs: [],
      status: (byType.get('path')?.length ?? 0) > 0 ? 'ready' : 'researching',
    },
  ]

  if (nodes.length === 0 && epNodes.length === 0) {
    steps.push({
      id: 'unmodeled-family',
      kind: 'unmodeled',
      nodeIds: [],
      cellRefs: [],
      status: 'blocked',
      note: `No graph nodes for family ${family}`,
    })
  }

  void index

  return PlannerPipelineSchema.parse({
    family: familyKey,
    generatedAt: new Date().toISOString(),
    source: 'graph',
    codegen: 'deferred',
    steps,
    unmodeledNodeIds: unmodeled,
    warnings: nodes.length === 0 && epNodes.length === 0
      ? [`unknown or empty family: ${family}`]
      : [],
  })
}

export function listPlannerFamilies(): string[] {
  const { graph } = loadSdkGraphWithTrust({
    mode: 'degraded',
    scanPlannerCitations: false,
    checkDebugGraph: false,
  })
  const set = new Set<string>()
  for (const n of Object.values(graph.nodes)) {
    if (String(n.family).startsWith('ep.')) set.add(String(n.family))
  }
  return [...set].sort()
}
